import { useState } from "react";
import { Link, Navigate, useLocation, useNavigate } from "react-router-dom";
import { Gamepad2, Lock, User } from "lucide-react";
import { toast } from "sonner";
import { useAuth } from "@/context/AuthContext";
import { Input } from "@/components/ui/input";

export default function LoginPage() {
  const { user, login } = useAuth();
  const nav = useNavigate();
  const loc = useLocation();
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState("");

  if (user) {
    const dest =
      user.role !== "owner" && user.status !== "approved"
        ? "/pending"
        : loc.state?.from || "/";
    return <Navigate to={dest} replace />;
  }

  const onSubmit = async (e) => {
    e.preventDefault();
    setErr("");
    setBusy(true);
    try {
      const u = await login(username.trim(), password);
      toast.success(`Welcome back, ${u.username}`);
      if (u.role !== "owner" && u.status !== "approved") nav("/pending");
      else nav(loc.state?.from || "/");
    } catch (e) {
      const msg = e?.response?.data?.detail || "Login failed";
      setErr(typeof msg === "string" ? msg : "Login failed");
    } finally {
      setBusy(false);
    }
  };

  return <AuthShell mode="login" onSubmit={onSubmit} busy={busy} err={err}
    username={username} setUsername={setUsername}
    password={password} setPassword={setPassword} />;
}

export function AuthShell({ mode, onSubmit, busy, err, username, setUsername, password, setPassword }) {
  const isLogin = mode === "login";
  return (
    <div className="min-h-screen w-full max-w-full overflow-x-hidden bg-[#fff7f0] flex flex-col">
      <div className="flex-1 w-full min-w-0 grid lg:grid-cols-2">
        {/* Left brand panel */}
        <div className="relative hidden min-w-0 lg:flex flex-col justify-between bg-[#1a1613] text-white px-12 py-12 overflow-hidden">
          <div className="flex min-w-0 items-center gap-3">
            <span className="grid shrink-0 place-items-center w-11 h-11 rounded-xl bg-[#ff6a00]">
              <Gamepad2 size={22} />
            </span>
            <span className="min-w-0 font-display font-bold text-2xl leading-tight">
              Learning <span className="text-[#ff6a00]">Games</span>
            </span>
          </div>
          <div className="relative z-10 max-w-md">
            <h2 className="font-display text-5xl font-extrabold leading-[1.02] tracking-tight">
              Members-only
              <br />
              <span className="text-[#ff6a00]">game lounge.</span>
            </h2>
            <p className="mt-5 text-white/70 max-w-md">
              3,000+ titles, one browser, zero downloads. Access is
              invite-only; the owner approves every new member personally.
            </p>
          </div>
          <div className="text-xs text-white/40">© {new Date().getFullYear()} — a private arcade</div>
          <div className="absolute -right-20 -bottom-20 w-[420px] h-[420px] rounded-full bg-[#ff6a00]/25 blur-3xl" />
        </div>

        {/* Right form */}
        <div className="min-w-0 flex items-center justify-center px-6 py-14">
          <form
            onSubmit={onSubmit}
            className="w-full max-w-md"
            data-testid={isLogin ? "login-form" : "register-form"}
          >
            <div className="lg:hidden flex items-center gap-2 mb-8">
              <span className="grid place-items-center w-9 h-9 rounded-xl bg-[#ff6a00] text-white">
                <Gamepad2 size={20} />
              </span>
              <span className="font-display font-bold text-lg">
                Learning <span className="text-[#ff6a00]">Games</span>
              </span>
            </div>

            <h1 className="font-display text-3xl sm:text-4xl font-extrabold tracking-tight">
              {isLogin ? "Welcome back." : "Request access."}
            </h1>
            <p className="mt-2 text-[#5c534d]">
              {isLogin
                ? "Sign in with your username and password."
                : "Create an account. The owner will review it before you can play."}
            </p>

            <div className="mt-8 space-y-4">
              <label className="block">
                <span className="text-xs font-semibold uppercase tracking-widest text-[#5c534d]">
                  Username
                </span>
                <div className="mt-1 relative">
                  <User size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-[#5c534d]" />
                  <Input
                    data-testid="username-input"
                    value={username}
                    onChange={(e) => setUsername(e.target.value)}
                    placeholder="e.g. CarterB"
                    className="pl-9 h-12 bg-white border-[#efe3d6] rounded-xl focus-visible:ring-2 focus-visible:ring-[#ff6a00] focus-visible:ring-offset-0 focus-visible:border-[#ff6a00]"
                    autoComplete="username"
                    required
                  />
                </div>
              </label>
              <label className="block">
                <span className="text-xs font-semibold uppercase tracking-widest text-[#5c534d]">
                  Password
                </span>
                <div className="mt-1 relative">
                  <Lock size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-[#5c534d]" />
                  <Input
                    data-testid="password-input"
                    type="password"
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    placeholder="••••••••"
                    className="pl-9 h-12 bg-white border-[#efe3d6] rounded-xl focus-visible:ring-2 focus-visible:ring-[#ff6a00] focus-visible:ring-offset-0 focus-visible:border-[#ff6a00]"
                    autoComplete={isLogin ? "current-password" : "new-password"}
                    minLength={6}
                    required
                  />
                </div>
              </label>
            </div>

            {err && (
              <p
                data-testid="auth-error"
                className="mt-4 text-sm text-red-600 bg-red-50 border border-red-100 rounded-lg px-3 py-2"
              >
                {err}
              </p>
            )}

            <button
              type="submit"
              disabled={busy}
              data-testid={isLogin ? "login-submit" : "register-submit"}
              className="mt-6 w-full h-12 rounded-xl bg-[#ff6a00] text-white font-semibold hover:bg-[#e85d00] disabled:opacity-60 transition-colors"
            >
              {busy ? "Please wait…" : isLogin ? "Sign in" : "Create account"}
            </button>

            <p className="mt-6 text-sm text-[#5c534d]">
              {isLogin ? (
                <>
                  Don&apos;t have an account?{" "}
                  <Link
                    to="/register"
                    data-testid="go-register"
                    className="font-semibold text-[#ff6a00] hover:underline"
                  >
                    Request access
                  </Link>
                </>
              ) : (
                <>
                  Already have one?{" "}
                  <Link
                    to="/login"
                    data-testid="go-login"
                    className="font-semibold text-[#ff6a00] hover:underline"
                  >
                    Sign in
                  </Link>
                </>
              )}
            </p>
          </form>
        </div>
      </div>
    </div>
  );
}
