import { useState } from "react";
import { Navigate, useNavigate } from "react-router-dom";
import { toast } from "sonner";
import { useAuth } from "@/context/AuthContext";
import { AuthShell } from "@/pages/LoginPage";

export default function RegisterPage() {
  const { user, register } = useAuth();
  const nav = useNavigate();
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState("");

  if (user) return <Navigate to={user.status === "approved" || user.role === "owner" ? "/" : "/pending"} replace />;

  const onSubmit = async (e) => {
    e.preventDefault();
    setErr("");
    setBusy(true);
    try {
      const u = await register(username.trim(), password);
      toast.success("Account created — awaiting owner approval");
      nav(u.role === "owner" || u.status === "approved" ? "/" : "/pending");
    } catch (e) {
      const msg = e?.response?.data?.detail || "Registration failed";
      setErr(typeof msg === "string" ? msg : "Registration failed");
    } finally {
      setBusy(false);
    }
  };

  return (
    <AuthShell
      mode="register"
      onSubmit={onSubmit}
      busy={busy}
      err={err}
      username={username}
      setUsername={setUsername}
      password={password}
      setPassword={setPassword}
    />
  );
}
